def jws_sign_hs256(header, payload, key):
    h = b64url(to_json(header))
    p = b64url(to_json(payload))
    signing_input = h + '.' + p
    sig = b64url(hmac_sha256(key, signing_input))
    return signing_input + '.' + sig  # Compact 직렬화

def jws_verify_hs256(token, key):
    h, p, sig = token.split('.')
    if parse_json(b64url_decode(h)).get('alg') != 'HS256':
        return False  # 기대한 alg만 허용(none 등 거부)
    expected = b64url(hmac_sha256(key, h + '.' + p))
    return const_time_eq(sig, expected)  # 타이밍 공격 방지
